pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;

    function setUp() public { c = new Owned(); admin = address(this); }

    function testFuzz_property(address newOwner) public {
        bool ok;
        bool ret;
        try c.setOwner(newOwner) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        assertTrue(!ok || ret);
    }
}
